  assert.deepEqual(pushWorkflowRule.run(textCtx({
    ".github/workflows/sched.yml": "name: S\non:\n  schedule:\n    - cron: '49 * * * *'\n  workflow_dispatch:\n",
  })), []);
  assert.deepEqual(pushWorkflowRule.run(textCtx({ "README.md": "hi" })), []);
});

